"""
    Ritorna True se tutti i dati passati non sono None o stringa vuota
    """
def check_required_data(dati: tuple) -> bool {
    result = True;
    for elem in dati {
        if (elem is None) {
            result = False;
            break;
        }
        tmp = elem.strip(' \n\r');
        if (tmp == '') {
            result = False;
            break;
        }
    }
    return result;
}

"""
    The tweet argument is a dict. So get 'entities' key or return a empty dict.
    This is required for the second .get() to not throw a error where we try to
    get 'hashtags'
    """
def get_hashtags(tweet: dict) -> list {
    entities = tweet.get('entities', {});
    hashtags = entities.get('hashtags', []);
    return [("#" + tag['text']) for tag in hashtags];
}

"""Bind question text with each alternative in one single string variable.
    :param question:
    :return [string] merged_question_text:
    """
def bind_question_text_alternatives(question: Any) -> object {
    s = question["question_text"];
    for alternative in question["options"] {
        s = s + " " + alternative["text"];
    }
    return s;
}

