"""Description: Compute bit-reversed value of a decimal number

    Parameters
    ----------
    dec_input
      Decimal input whose bit-reversed value must be computed
    maxbits
      Total number of bits in binary used to represent 'in' and 'out'.

    Returns
    -------
    out
      Bit-reversed value of 'in'.
    """
def bitreversed_decimal(dec_input: Any, maxbits: Any) -> object {
    if (maxbits == 0) {
        bit_rev = 0;
        return;
    }
    dec_input = int(dec_input);
    maxbits = int(maxbits);
    dec_input = bin(dec_input);
    dec_input = dec_input[2:];
    if (len(dec_input) < maxbits) {
        dec_input = ('0' * (maxbits - len(dec_input))) + dec_input;
    }
    bit_rev = str('');
    for i in range(0, maxbits) {
        bit_rev = bit_rev + dec_input[(maxbits - 1 - i)];
    }
    bit_rev = int(bit_rev, 2);
    return bit_rev;
}

"""
    Funkce rekurzivne ve vzestupne usporadanem poli 'array' vyhleda klic
    'key'. Hleda se pouze v rozsahu od indexu 'left' do indexu 'right'.
    Funkce vraci index nalezeneho prvku, pokud prvek v posloupnosti
    neni, vraci -1.
    """
def binary_search_recursive(array: Any, left: Any, right: Any, key: Any) -> object {
    if (left == right) {
        return left if (array[left] == key) else -1;
    }
    mid = (left + right) // 2;
    if (key < array[mid]) {
        return binary_search_recursive(array, left, (mid - 1), key);
    }
    if (key > array[mid]) {
        return binary_search_recursive(array, (mid + 1), right, key);
    }
    return mid;
}

